def fib(n):
    """返回第 n 个斐波那契数（fib(0)=0, fib(1)=1）。"""
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b
