def most_frequent(items):
    """返回出现最多的元素；并列时返回最先出现的。"""
    counts = {}
    for x in items:
        if x not in counts:
            counts[x] = [0, items.index(x)]
        counts[x][0] += 1
    return max(sorted(counts), key=lambda x: (-counts[x][0], counts[x][1]))
```

